mapper.sql:
WHERE x.row_year=#{year}
AND x.bill_stts_cd=#{status}
AND x.contract_type=#{type}
AND x.customer_id=#{customerId}
AND (x.project_name ILIKE '%' || #{q} || '%'
  OR x.bill_no ILIKE '%' || #{q} || '%' OR x.customer_name ILIKE '%' || #{q} || '%')

mapper.select:
SELECT x.* FROM () x 
ORDER BY x.${orderColumn} ${direction} NULLS LAST,x.bill_id DESC NULLS LAST,x.bill_stg_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT  FROM bill.bill b
JOIN prj.prj p ON p.prj_id=b.prj_id LEFT JOIN prj.bill_stg s ON s.bill_stg_id=b.bill_stg_id
WHERE b.bill_id=#{id}

mapper.sql:
b.prj_id=#{projectId} AND b.amnd_yn='N'

  AND b.bill_stg_id=#{stageId}
  AND b.atrb_ym=#{month}
